import { Theme } from "@astryxdesign/core";
import { useTheme } from "@astryxdesign/core";
import cedarTheme from "./theme";
import { PolicyEditor } from "./components";
import { useState } from "react";

// CSS 변수 타입 정의
type CssVar = `--${string}`;

/**
 * Playground 페이지 컴포넌트
 * PolicyEditor와 useTheme hook 사용 예시
 */
function PlaygroundPage() {
  const theme = useTheme();
  const [activeView, setActiveView] = useState<"playground" | "editor">("playground");

  // 토큰 접근 헬퍼
  const t = (name: string) => theme.token(name);

  const containerStyle: React.CSSProperties = {
    padding: "2rem",
    maxWidth: "1400px",
    margin: "0 auto",
  };

  const headerStyle: React.CSSProperties = {
    marginBottom: "2rem",
  };

  const titleStyle: React.CSSProperties = {
    fontSize: t("--text-heading-1-size"),
    fontWeight: Number(t("--text-heading-1-weight")),
    color: t("--color-text-primary"),
    marginBottom: "0.5rem",
  };

  const subtitleStyle: React.CSSProperties = {
    fontSize: t("--text-body-size"),
    color: t("--color-text-secondary"),
  };

  const tabContainerStyle: React.CSSProperties = {
    display: "flex",
    gap: "0.5rem",
    marginBottom: "1.5rem",
    borderBottom: `1px solid ${t("--color-border-default")}`,
    paddingBottom: "0.5rem",
  };

  const tabStyle = (isActive: boolean): React.CSSProperties => ({
    padding: "0.75rem 1.5rem",
    borderRadius: `${t("--radius-element")} ${t("--radius-element")} 0 0`,
    border: "none",
    borderBottom: isActive ? `2px solid ${t("--color-accent")}` : "2px solid transparent",
    backgroundColor: "transparent",
    color: isActive ? t("--color-accent") : t("--color-text-secondary"),
    cursor: "pointer",
    fontWeight: isActive ? 600 : 400,
    fontSize: "0.875rem",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  });

  const cardStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-element"),
    backgroundColor: t("--color-background-primary"),
    border: `1px solid ${t("--color-border-default")}`,
    marginBottom: "1rem",
  };

  const gridStyle: React.CSSProperties = {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "1rem",
    marginTop: "1.5rem",
  };

  const badgeStyle: React.CSSProperties = {
    display: "inline-block",
    padding: "0.25rem 0.75rem",
    borderRadius: "9999px",
    fontSize: "0.875rem",
    fontWeight: 500,
    backgroundColor: t("--color-accent"),
    color: "white",
  };

  const handleSavePolicy = async (cedarJson: string, name: string) => {
    console.log("Saving policy:", { name, cedarJson });
    // API 호출 로직은 later 구현
    alert(`정책 "${name}"이(가) 저장되었습니다!`);
  };

  const handleCancelPolicy = () => {
    console.log("Policy editing cancelled");
  };

  return (
    <div style={containerStyle}>
      <header style={headerStyle}>
        <h1 style={titleStyle}>Cedar Example Playground</h1>
        <p style={subtitleStyle}>
          Current theme mode: {theme.mode} (system)
        </p>
      </header>

      <div style={tabContainerStyle}>
        <button
          style={tabStyle(activeView === "playground")}
          onClick={() => setActiveView("playground")}
        >
          Theme Playground
        </button>
        <button
          style={tabStyle(activeView === "editor")}
          onClick={() => setActiveView("editor")}
        >
          Policy Editor
        </button>
      </div>

      {activeView === "playground" && (
        <>
          <div style={gridStyle}>
            <div style={cardStyle}>
              <span style={badgeStyle}>Theme Active</span>
              <h2 style={{ marginTop: "1rem", marginBottom: "0.5rem", color: t("--color-text-primary") }}>Custom Theme</h2>
              <p style={{ color: t("--color-text-secondary") }}>
                이 페이지는 Astryx Design System의 커스텀 테마를 사용하여 스타일링되었습니다.
              </p>
            </div>

            <div style={cardStyle}>
              <h2 style={{ marginBottom: "0.5rem", color: t("--color-text-primary") }}>Design Tokens</h2>
              <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
                <div>
                  <strong>Accent:</strong>{" "}
                  <span style={{ color: t("--color-accent") }}>
                    {t("--color-accent")}
                  </span>
                </div>
                <div>
                  <strong>Background:</strong>{" "}
                  <span style={{ color: t("--color-background-primary") }}>
                    {t("--color-background-primary")}
                  </span>
                </div>
              </div>
            </div>

            <div style={cardStyle}>
              <h2 style={{ marginBottom: "0.5rem", color: t("--color-text-primary") }}>Motion</h2>
              <p style={{ color: t("--color-text-secondary") }}>
                애니메이션 지속 시간:
                <br />
                Fast: {theme.tokens["--duration-fast"] || "150ms"}
                <br />
                Medium: {theme.tokens["--duration-medium"] || "300ms"}
              </p>
            </div>
          </div>

          <div style={{ marginTop: "2rem", display: "flex", gap: "1rem" }}>
            <button
              onClick={() => {}}
              style={{
                padding: "0.5rem 1rem",
                borderRadius: t("--radius-element"),
                border: `1px solid ${t("--color-border-default")}`,
                backgroundColor: "transparent",
                cursor: "pointer",
              }}
            >
              Light Mode
            </button>
            <button
              onClick={() => {}}
              style={{
                padding: "0.5rem 1rem",
                borderRadius: t("--radius-element"),
                border: `1px solid ${t("--color-border-default")}`,
                backgroundColor: "transparent",
                cursor: "pointer",
              }}
            >
              Dark Mode
            </button>
            <button
              onClick={() => {}}
              style={{
                padding: "0.5rem 1rem",
                borderRadius: t("--radius-element"),
                border: `1px solid ${t("--color-border-default")}`,
                backgroundColor: "transparent",
                cursor: "pointer",
              }}
            >
              System Mode
            </button>
          </div>
        </>
      )}

      {activeView === "editor" && (
        <PolicyEditor
          onSave={handleSavePolicy}
          onCancel={handleCancelPolicy}
        />
      )}
    </div>
  );
}

/**
 * App 컴포넌트
 * Theme Provider로 전체 앱을 감싸서 커스텀 테마를 적용합니다.
 */
function App() {
  return (
    <Theme theme={cedarTheme} mode="system">
      <PlaygroundPage />
    </Theme>
  );
}

export default App;

import React from "react";
import { useTheme } from "@astryxdesign/core";
import type { Step } from "../types/policy";

/**
 * StepperProgress Props
 */
export interface StepperProgressProps {
  steps: Step[];
  currentStep: number;
  completedSteps: number[];
  onStepClick: (index: number) => void;
  disabled?: boolean;
}

/**
 * StepperProgress 컴포넌트
 * 4단계 네비게이션을 제공하는 Stepper UI
 */
export const StepperProgress: React.FC<StepperProgressProps> = ({
  steps,
  currentStep,
  completedSteps,
  onStepClick,
  disabled = false,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const containerStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: "1rem",
    backgroundColor: t("--color-background-secondary"),
    borderRadius: t("--radius-element"),
    marginBottom: "1.5rem",
  };

  const stepWrapperStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    flex: 1,
    justifyContent: "space-between",
  };

  const getStepStyle = (index: number): React.CSSProperties => {
    const isCompleted = completedSteps.includes(index);
    const isCurrent = currentStep === index;
    const isPast = index < currentStep || isCompleted;

    return {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      gap: "0.5rem",
      cursor: disabled ? "not-allowed" : isPast ? "pointer" : "default",
      opacity: disabled ? 0.5 : 1,
      transition: `opacity ${theme.tokens["--duration-fast"] || "150ms"}`,
    };
  };

  const getCircleStyle = (index: number): React.CSSProperties => {
    const isCompleted = completedSteps.includes(index);
    const isCurrent = currentStep === index;

    let backgroundColor = t("--color-background-tertiary");
    let borderColor = t("--color-border-default");
    let color = t("--color-text-secondary");

    if (isCompleted) {
      backgroundColor = t("--color-accent");
      borderColor = t("--color-accent");
      color = "white";
    } else if (isCurrent) {
      backgroundColor = t("--color-accent");
      borderColor = t("--color-accent");
      color = "white";
    }

    return {
      width: "36px",
      height: "36px",
      borderRadius: "50%",
      border: `2px solid ${borderColor}`,
      backgroundColor,
      color,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontWeight: 600,
      fontSize: "0.875rem",
      transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    };
  };

  const getConnectorStyle = (index: number): React.CSSProperties => {
    const isPast = index < currentStep || completedSteps.includes(index);

    return {
      flex: 1,
      height: "2px",
      backgroundColor: isPast
        ? t("--color-accent")
        : t("--color-border-default"),
      margin: "0 0.5rem",
      transition: `background-color ${theme.tokens["--duration-fast"] || "150ms"}`,
    };
  };

  const getLabelStyle = (index: number): React.CSSProperties => {
    const isCurrent = currentStep === index;

    return {
      fontSize: "0.75rem",
      fontWeight: isCurrent ? 600 : 400,
      color: isCurrent
        ? t("--color-text-primary")
        : t("--color-text-secondary"),
      textAlign: "center" as const,
      whiteSpace: "nowrap" as const,
    };
  };

  return (
    <div style={containerStyle}>
      <div style={stepWrapperStyle}>
        {steps.map((step, index) => (
          <React.Fragment key={step.id}>
            <div
              style={getStepStyle(index)}
              onClick={() => !disabled && (index <= currentStep || completedSteps.includes(index)) && onStepClick(index)}
              role="button"
              tabIndex={disabled ? -1 : 0}
              aria-label={`Step ${step.id}: ${step.title}`}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  !disabled && (index <= currentStep || completedSteps.includes(index)) && onStepClick(index);
                }
              }}
            >
              <div style={getCircleStyle(index)}>
                {completedSteps.includes(index) ? "✓" : step.id}
              </div>
              <span style={getLabelStyle(index)}>{step.title}</span>
            </div>
            {index < steps.length - 1 && (
              <div
                style={getConnectorStyle(index)}
              />
            )}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

export default StepperProgress;

import React from "react";
import { useTheme } from "@astryxdesign/core";

/**
 * SelectionCard Props
 */
export interface SelectionCardProps {
  title: string;
  description?: string;
  icon?: React.ReactNode;
  selected: boolean;
  onClick: () => void;
  disabled?: boolean;
}

/**
 * SelectionCard 컴포넌트
 * 클릭 가능한 카드 형태의 선택 요소
 */
export const SelectionCard: React.FC<SelectionCardProps> = ({
  title,
  description,
  icon,
  selected,
  onClick,
  disabled = false,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const cardStyle: React.CSSProperties = {
    position: "relative" as const,
    padding: "1rem",
    borderRadius: t("--radius-element"),
    border: `2px solid ${selected ? t("--color-accent") : t("--color-border-default")}`,
    backgroundColor: selected
      ? `${t("--color-accent")}15`
      : t("--color-background-primary"),
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.5 : 1,
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    minWidth: "140px",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    textAlign: "center" as const,
    gap: "0.5rem",
  };

  const handleMouseEnter = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!disabled) {
      e.currentTarget.style.backgroundColor = selected
        ? `${t("--color-accent")}25`
        : `${t("--color-accent")}10`;
      e.currentTarget.style.borderColor = t("--color-accent");
    }
  };

  const handleMouseLeave = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!disabled) {
      e.currentTarget.style.backgroundColor = selected
        ? `${t("--color-accent")}15`
        : t("--color-background-primary");
      e.currentTarget.style.borderColor = selected
        ? t("--color-accent")
        : t("--color-border-default");
    }
  };

  const checkIconStyle: React.CSSProperties = {
    position: "absolute" as const,
    top: "-8px",
    right: "-8px",
    width: "24px",
    height: "24px",
    borderRadius: "50%",
    backgroundColor: t("--color-accent"),
    color: "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: "0.75rem",
    fontWeight: "bold",
    boxShadow: "0 2px 4px rgba(0, 0, 0, 0.2)",
    opacity: selected ? 1 : 0,
    transform: selected ? "scale(1)" : "scale(0.5)",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const radioStyle: React.CSSProperties = {
    width: "20px",
    height: "20px",
    borderRadius: "50%",
    border: `2px solid ${selected ? t("--color-accent") : t("--color-border-default")}`,
    backgroundColor: selected ? t("--color-accent") : "transparent",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const innerDotStyle: React.CSSProperties = {
    width: "8px",
    height: "8px",
    borderRadius: "50%",
    backgroundColor: "white",
    opacity: selected ? 1 : 0,
    transition: `opacity ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
  };

  const descriptionStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    margin: 0,
  };

  const handleClick = () => {
    if (!disabled) {
      onClick();
    }
  };

  return (
    <div
      style={cardStyle}
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role="checkbox"
      aria-checked={selected}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={(e) => {
        if ((e.key === "Enter" || e.key === " ") && !disabled) {
          e.preventDefault();
          onClick();
        }
      }}
    >
      {selected && (
        <div style={checkIconStyle}>
          ✓
        </div>
      )}
      <div style={radioStyle}>
        <div style={innerDotStyle} />
      </div>
      {icon && <div>{icon}</div>}
      <h4 style={titleStyle}>{title}</h4>
      {description && <p style={descriptionStyle}>{description}</p>}
    </div>
  );
};

export default SelectionCard;

import React from "react";
import { useTheme } from "@astryxdesign/core";

/**
 * StepContainer Props
 */
export interface StepContainerProps {
  title: string;
  subtitle?: string;
  showBulkActions?: boolean;
  onSelectAll: () => void;
  onSelectNone: () => void;
  error?: string;
  children: React.ReactNode;
}

/**
 * StepContainer 컴포넌트
 * 스텝 콘텐츠와 전체선택/전체해제 버튼을 제공하는 컨테이너
 */
export const StepContainer: React.FC<StepContainerProps> = ({
  title,
  subtitle,
  showBulkActions = false,
  onSelectAll,
  onSelectNone,
  error,
  children,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const containerStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-element"),
    backgroundColor: t("--color-background-primary"),
    border: `1px solid ${error ? "#ef4444" : t("--color-border-default")}`,
  };

  const headerStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    marginBottom: "1rem",
    flexWrap: "wrap" as const,
    gap: "0.5rem",
  };

  const titleWrapperStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column" as const,
    gap: "0.25rem",
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
  };

  const subtitleStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    margin: 0,
  };

  const bulkActionsStyle: React.CSSProperties = {
    display: "flex",
    gap: "0.5rem",
  };

  const buttonBaseStyle: React.CSSProperties = {
    padding: "0.25rem 0.75rem",
    fontSize: "0.75rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    border: "none",
  };

  const selectAllButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: t("--color-accent"),
    color: "white",
  };

  const selectNoneButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: "transparent",
    color: t("--color-text-secondary"),
    border: `1px solid ${t("--color-border-default")}`,
  };

  const contentStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap" as const,
    gap: "1rem",
    justifyContent: "flex-start",
  };

  const errorStyle: React.CSSProperties = {
    marginTop: "1rem",
    padding: "0.75rem",
    borderRadius: t("--radius-element"),
    backgroundColor: "#fef2f2",
    border: "1px solid #fecaca",
    color: "#dc2626",
    fontSize: "0.875rem",
  };

  return (
    <div style={containerStyle}>
      <div style={headerStyle}>
        <div style={titleWrapperStyle}>
          <h3 style={titleStyle}>{title}</h3>
          {subtitle && <p style={subtitleStyle}>{subtitle}</p>}
        </div>
        {showBulkActions && (
          <div style={bulkActionsStyle}>
            <button
              style={selectAllButtonStyle}
              onClick={onSelectAll}
              type="button"
            >
              Select All
            </button>
            <button
              style={selectNoneButtonStyle}
              onClick={onSelectNone}
              type="button"
            >
              None
            </button>
          </div>
        )}
      </div>
      <div style={contentStyle}>
        {children}
      </div>
      {error && (
        <div style={errorStyle}>
          {error}
        </div>
      )}
    </div>
  );
};

export default StepContainer;

import React, { useState, useMemo, useCallback } from "react";
import { useTheme } from "@astryxdesign/core";
import { StepperProgress } from "./StepperProgress";
import { SelectionCard } from "./SelectionCard";
import { StepContainer } from "./StepContainer";
import type {
  CedarPolicy,
  PolicyFormState,
  Step,
  StepValidation,
} from "../types/policy";

/**
 * PolicyEditor Props
 */
export interface PolicyEditorProps {
  onSave?: (cedarJson: string, name: string) => Promise<void>;
  onCancel?: () => void;
  initialData?: Partial<CedarPolicy>;
}

/**
 * PolicyEditor 컴포넌트
 * Forbid 정책을 편집하는 Stepper 기반 폼 인터페이스
 */
export const PolicyEditor: React.FC<PolicyEditorProps> = ({
  onSave,
  onCancel,
  initialData,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  // 스텝 정의
  const steps: Step[] = [
    { id: 1, title: "Principal", required: true, description: "역할 선택" },
    { id: 2, title: "Resource", required: true, description: "리소스 유형 선택" },
    { id: 3, title: "Action", required: true, description: "작업 선택 (다중)" },
    { id: 4, title: "Condition", required: false, description: "조건 입력 (선택)" },
  ];

  // 폼 상태
  const [formState, setFormState] = useState<PolicyFormState>({
    name: "",
    principalRole: initialData?.principal?.role || null,
    resourceType: initialData?.resource?.type || null,
    actions: initialData?.action ? [initialData.action] : [],
    conditionExpression: initialData?.condition?.expression || "",
    conditionDescription: initialData?.condition?.description || "",
  });

  // 현재 스텝
  const [currentStep, setCurrentStep] = useState(0);

  // 완료된 스텝
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);

  // 저장 상태
  const [isSaving, setIsSaving] = useState(false);

  // 에러 메시지
  const [errors, setErrors] = useState<Record<number, string>>({});

  // Principal 옵션
  const principalOptions = [
    { value: "admin" as const, label: "Admin", description: "전체 권한" },
    { value: "editor" as const, label: "Editor", description: "편집 권한" },
    { value: "viewer" as const, label: "Viewer", description: "조회 권한" },
  ];

  // Resource 옵션
  const resourceOptions = [
    { value: "document" as const, label: "Document", description: "문서 리소스" },
    { value: "issue" as const, label: "Issue", description: "이슈 리소스" },
  ];

  // Action 옵션
  const actionOptions = [
    { value: "read" as const, label: "Read", description: "읽기 작업" },
    { value: "write" as const, label: "Write", description: "쓰기 작업" },
    { value: "delete" as const, label: "Delete", description: "삭제 작업" },
  ];

  // 스텝 유효성 검사
  const validateStep = useCallback((stepIndex: number): StepValidation => {
    switch (stepIndex) {
      case 0:
        if (!formState.name.trim()) {
          return { isValid: false, error: "정책 이름을 입력하세요" };
        }
        if (formState.name.length > 100) {
          return { isValid: false, error: "정책 이름은 100자 이내여야 합니다" };
        }
        if (!formState.principalRole) {
          return { isValid: false, error: "Principal 역할을 선택하세요" };
        }
        return { isValid: true };
      case 1:
        if (!formState.resourceType) {
          return { isValid: false, error: "Resource 유형을 선택하세요" };
        }
        return { isValid: true };
      case 2:
        if (formState.actions.length === 0) {
          return { isValid: false, error: "최소 하나 이상의 Action을 선택하세요" };
        }
        return { isValid: true };
      case 3:
        return { isValid: true };
      default:
        return { isValid: true };
    }
  }, [formState]);

  // 전체 유효성 검사
  const isAllValid = useMemo(() => {
    return (
      formState.name.trim().length > 0 &&
      formState.name.length <= 100 &&
      formState.principalRole !== null &&
      formState.resourceType !== null &&
      formState.actions.length > 0
    );
  }, [formState]);

  // Cedar JSON 생성
  const cedarJson = useMemo(() => {
    const policy: CedarPolicy = {
      effect: "forbid",
      principal: {
        role: formState.principalRole || "viewer",
      },
      resource: {
        type: formState.resourceType || "document",
      },
      action: formState.actions[0] || "read",
    };

    if (formState.conditionExpression.trim()) {
      policy.condition = {
        expression: formState.conditionExpression,
        description: formState.conditionDescription || formState.conditionExpression,
      };
    }

    return JSON.stringify(policy, null, 2);
  }, [formState]);

  // Principal 선택
  const handlePrincipalSelect = (value: "admin" | "editor" | "viewer") => {
    setFormState((prev) => ({ ...prev, principalRole: value }));
    setErrors((prev) => ({ ...prev, 0: "" }));
  };

  // Resource 선택
  const handleResourceSelect = (value: "document" | "issue") => {
    setFormState((prev) => ({ ...prev, resourceType: value }));
    setErrors((prev) => ({ ...prev, 1: "" }));
  };

  // Action 토글
  const handleActionToggle = (value: "read" | "write" | "delete") => {
    setFormState((prev) => {
      const exists = prev.actions.includes(value);
      return {
        ...prev,
        actions: exists
          ? prev.actions.filter((a) => a !== value)
          : [...prev.actions, value],
      };
    });
    setErrors((prev) => ({ ...prev, 2: "" }));
  };

  // 전체 Action 선택
  const handleSelectAllActions = () => {
    setFormState((prev) => ({
      ...prev,
      actions: actionOptions.map((a) => a.value),
    }));
    setErrors((prev) => ({ ...prev, 2: "" }));
  };

  // 전체 Action 해제
  const handleSelectNoneActions = () => {
    setFormState((prev) => ({ ...prev, actions: [] }));
  };

  // 다음 스텝
  const handleNext = () => {
    const validation = validateStep(currentStep);
    if (!validation.isValid) {
      setErrors((prev) => ({ ...prev, [currentStep]: validation.error || "" }));
      return;
    }

    if (!completedSteps.includes(currentStep)) {
      setCompletedSteps((prev) => [...prev, currentStep]);
    }

    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    }
  };

  // 이전 스텝
  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  // 스텝 클릭
  const handleStepClick = (index: number) => {
    if (index <= currentStep || completedSteps.includes(index)) {
      setCurrentStep(index);
    }
  };

  // 저장
  const handleSave = async () => {
    if (!isAllValid) {
      return;
    }

    setIsSaving(true);
    try {
      if (onSave) {
        await onSave(cedarJson, formState.name);
      }
      // 폼 초기화
      setFormState({
        name: "",
        principalRole: null,
        resourceType: null,
        actions: [],
        conditionExpression: "",
        conditionDescription: "",
      });
      setCurrentStep(0);
      setCompletedSteps([]);
    } catch (error) {
      console.error("Save failed:", error);
    } finally {
      setIsSaving(false);
    }
  };

  // 취소
  const handleCancel = () => {
    if (onCancel) {
      onCancel();
    }
  };

  // 스타일 정의
  const containerStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-container"),
    backgroundColor: t("--color-background-primary"),
    border: `1px solid ${t("--color-border-default")}`,
    maxWidth: "800px",
    margin: "0 auto",
  };

  const headerStyle: React.CSSProperties = {
    marginBottom: "1.5rem",
    paddingBottom: "1rem",
    borderBottom: `1px solid ${t("--color-border-default")}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1.25rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
    marginBottom: "1rem",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "0.75rem",
    fontSize: "0.875rem",
    borderRadius: t("--radius-element"),
    border: `1px solid ${errors[0] ? "#ef4444" : t("--color-border-default")}`,
    backgroundColor: t("--color-background-primary"),
    color: t("--color-text-primary"),
    outline: "none",
    boxSizing: "border-box" as const,
  };

  const navigationStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    marginTop: "1.5rem",
    gap: "1rem",
  };

  const buttonBaseStyle: React.CSSProperties = {
    padding: "0.75rem 1.5rem",
    fontSize: "0.875rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    border: "none",
  };

  const primaryButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: t("--color-accent"),
    color: "white",
    opacity: isAllValid ? 1 : 0.5,
    cursor: isAllValid && !isSaving ? "pointer" : "not-allowed",
  };

  const secondaryButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: "transparent",
    color: t("--color-text-secondary"),
    border: `1px solid ${t("--color-border-default")}`,
  };

  const previewContainerStyle: React.CSSProperties = {
    marginTop: "1.5rem",
    padding: "1rem",
    borderRadius: t("--radius-element"),
    backgroundColor: t("--color-background-secondary"),
    border: `1px solid ${t("--color-border-default")}`,
  };

  const previewTitleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    marginBottom: "0.5rem",
  };

  const codeBlockStyle: React.CSSProperties = {
    fontFamily: "JetBrains Mono, monospace",
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    whiteSpace: "pre-wrap" as const,
    wordBreak: "break-all" as const,
    margin: 0,
    padding: "0.75rem",
    backgroundColor: t("--color-background-tertiary"),
    borderRadius: t("--radius-inner"),
    overflow: "auto" as const,
    maxHeight: "200px",
  };

  const footerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    marginTop: "1.5rem",
    paddingTop: "1rem",
    borderTop: `1px solid ${t("--color-border-default")}`,
  };

  // 스텝 콘텐츠 렌더링
  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div>
            <div style={{ marginBottom: "1rem" }}>
              <label
                htmlFor="policyName"
                style={{
                  display: "block",
                  marginBottom: "0.5rem",
                  fontSize: "0.875rem",
                  fontWeight: 500,
                  color: t("--color-text-primary"),
                }}
              >
                Policy Name *
              </label>
              <input
                id="policyName"
                type="text"
                value={formState.name}
                onChange={(e) => {
                  setFormState((prev) => ({ ...prev, name: e.target.value }));
                  setErrors((prev) => ({ ...prev, 0: "" }));
                }}
                placeholder="정책 이름을 입력하세요"
                style={inputStyle}
              />
            </div>
            <StepContainer
              title="Principal (Role)"
              subtitle="역할을 선택하세요"
              error={errors[0]}
              onSelectAll={() => {}}
              onSelectNone={() => {}}
            >
              {principalOptions.map((option) => (
                <SelectionCard
                  key={option.value}
                  title={option.label}
                  description={option.description}
                  selected={formState.principalRole === option.value}
                  onClick={() => handlePrincipalSelect(option.value)}
                />
              ))}
            </StepContainer>
          </div>
        );

      case 1:
        return (
          <StepContainer
            title="Resource Type"
            subtitle="리소스 유형을 선택하세요"
            error={errors[1]}
            onSelectAll={() => {}}
            onSelectNone={() => {}}
          >
            {resourceOptions.map((option) => (
              <SelectionCard
                key={option.value}
                title={option.label}
                description={option.description}
                selected={formState.resourceType === option.value}
                onClick={() => handleResourceSelect(option.value)}
              />
            ))}
          </StepContainer>
        );

      case 2:
        return (
          <StepContainer
            title="Action"
            subtitle="작업을 선택하세요 (다중 선택 가능)"
            showBulkActions
            error={errors[2]}
            onSelectAll={handleSelectAllActions}
            onSelectNone={handleSelectNoneActions}
          >
            {actionOptions.map((option) => (
              <SelectionCard
                key={option.value}
                title={option.label}
                description={option.description}
                selected={formState.actions.includes(option.value)}
                onClick={() => handleActionToggle(option.value)}
              />
            ))}
          </StepContainer>
        );

      case 3:
        return (
          <StepContainer
            title="Condition (선택)"
            subtitle="조건 표현식을 입력하세요 (선택사항)"
            onSelectAll={() => {}}
            onSelectNone={() => {}}
          >
            <div style={{ width: "100%" }}>
              <label
                htmlFor="conditionExpression"
                style={{
                  display: "block",
                  marginBottom: "0.5rem",
                  fontSize: "0.875rem",
                  fontWeight: 500,
                  color: t("--color-text-primary"),
                }}
              >
                Condition Expression
              </label>
              <input
                id="conditionExpression"
                type="text"
                value={formState.conditionExpression}
                onChange={(e) =>
                  setFormState((prev) => ({
                    ...prev,
                    conditionExpression: e.target.value,
                  }))
                }
                placeholder='예: resource.ownerId == principal.id'
                style={{
                  ...inputStyle,
                  fontFamily: "JetBrains Mono, monospace",
                }}
              />
              <div style={{ marginTop: "1rem" }}>
                <label
                  htmlFor="conditionDescription"
                  style={{
                    display: "block",
                    marginBottom: "0.5rem",
                    fontSize: "0.875rem",
                    fontWeight: 500,
                    color: t("--color-text-primary"),
                  }}
                >
                  Condition Description (선택)
                </label>
                <input
                  id="conditionDescription"
                  type="text"
                  value={formState.conditionDescription}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      conditionDescription: e.target.value,
                    }))
                  }
                  placeholder="조건에 대한 설명을 입력하세요"
                  style={inputStyle}
                />
              </div>
            </div>
          </StepContainer>
        );

      default:
        return null;
    }
  };

  return (
    <div style={containerStyle}>
      <header style={headerStyle}>
        <h2 style={titleStyle}>Policy Editor</h2>
      </header>

      <StepperProgress
        steps={steps}
        currentStep={currentStep}
        completedSteps={completedSteps}
        onStepClick={handleStepClick}
      />

      {renderStepContent()}

      <div style={navigationStyle}>
        <button
          style={secondaryButtonStyle}
          onClick={handlePrevious}
          disabled={currentStep === 0}
          type="button"
        >
          ← Previous
        </button>
        {currentStep < steps.length - 1 ? (
          <button
            style={primaryButtonStyle}
            onClick={handleNext}
            type="button"
          >
            Next →
          </button>
        ) : (
          <div />
        )}
      </div>

      <div style={previewContainerStyle}>
        <h3 style={previewTitleStyle}>Cedar JSON Preview</h3>
        <pre style={codeBlockStyle}>{cedarJson}</pre>
      </div>

      <footer style={footerStyle}>
        <button
          style={secondaryButtonStyle}
          onClick={handleCancel}
          type="button"
        >
          Cancel
        </button>
        <button
          style={primaryButtonStyle}
          onClick={handleSave}
          disabled={!isAllValid || isSaving}
          type="button"
        >
          {isSaving ? "Saving..." : "Save Policy"}
        </button>
      </footer>
    </div>
  );
};

export default PolicyEditor;

