import React from "react";
import { useTheme } from "@astryxdesign/core";

/**
 * SelectionCard Props
 */
export interface SelectionCardProps {
  title: string;
  description?: string;
  icon?: React.ReactNode;
  selected: boolean;
  onClick: () => void;
  disabled?: boolean;
}

/**
 * SelectionCard 컴포넌트
 * 클릭 가능한 카드 형태의 선택 요소
 */
export const SelectionCard: React.FC<SelectionCardProps> = ({
  title,
  description,
  icon,
  selected,
  onClick,
  disabled = false,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const cardStyle: React.CSSProperties = {
    position: "relative" as const,
    padding: "1rem",
    borderRadius: t("--radius-element"),
    border: `2px solid ${selected ? t("--color-accent") : t("--color-border")}`,
    backgroundColor: selected
      ? `${t("--color-accent")}15`
      : t("--color-background-surface"),
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.5 : 1,
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    minWidth: "140px",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    textAlign: "center" as const,
    gap: "0.5rem",
  };

  const handleMouseEnter = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!disabled) {
      e.currentTarget.style.backgroundColor = selected
        ? `${t("--color-accent")}25`
        : `${t("--color-accent")}10`;
      e.currentTarget.style.borderColor = t("--color-accent");
    }
  };

  const handleMouseLeave = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!disabled) {
      e.currentTarget.style.backgroundColor = selected
        ? `${t("--color-accent")}15`
        : t("--color-background-surface");
      e.currentTarget.style.borderColor = selected
        ? t("--color-accent")
        : t("--color-border");
    }
  };

  const checkIconStyle: React.CSSProperties = {
    position: "absolute" as const,
    top: "-8px",
    right: "-8px",
    width: "24px",
    height: "24px",
    borderRadius: "50%",
    backgroundColor: t("--color-accent"),
    color: "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: "0.75rem",
    fontWeight: "bold",
    boxShadow: "0 2px 4px rgba(0, 0, 0, 0.2)",
    opacity: selected ? 1 : 0,
    transform: selected ? "scale(1)" : "scale(0.5)",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const radioStyle: React.CSSProperties = {
    width: "20px",
    height: "20px",
    borderRadius: "50%",
    border: `2px solid ${selected ? t("--color-accent") : t("--color-border")}`,
    backgroundColor: selected ? t("--color-accent") : "transparent",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const innerDotStyle: React.CSSProperties = {
    width: "8px",
    height: "8px",
    borderRadius: "50%",
    backgroundColor: "white",
    opacity: selected ? 1 : 0,
    transition: `opacity ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
  };

  const descriptionStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    margin: 0,
  };

  const handleClick = () => {
    if (!disabled) {
      onClick();
    }
  };

  return (
    <div
      style={cardStyle}
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role="checkbox"
      aria-checked={selected}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={(e) => {
        if ((e.key === "Enter" || e.key === " ") && !disabled) {
          e.preventDefault();
          onClick();
        }
      }}
    >
      {selected && (
        <div style={checkIconStyle}>
          ✓
        </div>
      )}
      <div style={radioStyle}>
        <div style={innerDotStyle} />
      </div>
      {icon && <div>{icon}</div>}
      <h4 style={titleStyle}>{title}</h4>
      {description && <p style={descriptionStyle}>{description}</p>}
    </div>
  );
};

export default SelectionCard;

import React from "react";
import { useTheme } from "@astryxdesign/core";

/**
 * StepContainer Props
 */
export interface StepContainerProps {
  title: string;
  subtitle?: string;
  showBulkActions?: boolean;
  onSelectAll: () => void;
  onSelectNone: () => void;
  error?: string;
  children: React.ReactNode;
}

/**
 * StepContainer 컴포넌트
 * 스텝 콘텐츠와 전체선택/전체해제 버튼을 제공하는 컨테이너
 */
export const StepContainer: React.FC<StepContainerProps> = ({
  title,
  subtitle,
  showBulkActions = false,
  onSelectAll,
  onSelectNone,
  error,
  children,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const containerStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-element"),
    backgroundColor: t("--color-background-surface"),
    border: `1px solid ${error ? "#ef4444" : t("--color-border")}`,
  };

  const headerStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    marginBottom: "1rem",
    flexWrap: "wrap" as const,
    gap: "0.5rem",
  };

  const titleWrapperStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column" as const,
    gap: "0.25rem",
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
  };

  const subtitleStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    margin: 0,
  };

  const bulkActionsStyle: React.CSSProperties = {
    display: "flex",
    gap: "0.5rem",
  };

  const buttonBaseStyle: React.CSSProperties = {
    padding: "0.25rem 0.75rem",
    fontSize: "0.75rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    border: "none",
  };

  const selectAllButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: t("--color-accent"),
    color: "white",
  };

  const selectNoneButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: "transparent",
    color: t("--color-text-secondary"),
    border: `1px solid ${t("--color-border")}`,
  };

  const contentStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap" as const,
    gap: "1rem",
    justifyContent: "flex-start",
  };

  const errorStyle: React.CSSProperties = {
    marginTop: "1rem",
    padding: "0.75rem",
    borderRadius: t("--radius-element"),
    backgroundColor: "#fef2f2",
    border: "1px solid #fecaca",
    color: "#dc2626",
    fontSize: "0.875rem",
  };

  return (
    <div style={containerStyle}>
      <div style={headerStyle}>
        <div style={titleWrapperStyle}>
          <h3 style={titleStyle}>{title}</h3>
          {subtitle && <p style={subtitleStyle}>{subtitle}</p>}
        </div>
        {showBulkActions && (
          <div style={bulkActionsStyle}>
            <button
              style={selectAllButtonStyle}
              onClick={onSelectAll}
              type="button"
            >
              Select All
            </button>
            <button
              style={selectNoneButtonStyle}
              onClick={onSelectNone}
              type="button"
            >
              None
            </button>
          </div>
        )}
      </div>
      <div style={contentStyle}>
        {children}
      </div>
      {error && (
        <div style={errorStyle}>
          {error}
        </div>
      )}
    </div>
  );
};

export default StepContainer;

import React, { useState, useMemo, useCallback } from "react";
import { useTheme } from "@astryxdesign/core";
import { StepperProgress } from "./StepperProgress";
import { SelectionCard } from "./SelectionCard";
import { StepContainer } from "./StepContainer";
import type {
  CedarPolicy,
  PolicyFormState,
  Step,
  StepValidation,
} from "../types/policy";

/**
 * PolicyEditor Props
 */
export interface PolicyEditorProps {
  onSave?: (cedarJson: string, name: string) => Promise<void>;
  onCancel?: () => void;
  initialData?: Partial<CedarPolicy>;
}

/**
 * PolicyEditor 컴포넌트
 * Forbid 정책을 편집하는 Stepper 기반 폼 인터페이스
 */
export const PolicyEditor: React.FC<PolicyEditorProps> = ({
  onSave,
  onCancel,
  initialData,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  // 스텝 정의
  const steps: Step[] = [
    { id: 1, title: "Principal", required: true, description: "역할 선택" },
    { id: 2, title: "Resource", required: true, description: "리소스 유형 선택" },
    { id: 3, title: "Action", required: true, description: "작업 선택 (다중)" },
    { id: 4, title: "Condition", required: false, description: "조건 입력 (선택)" },
  ];

  // 폼 상태
  const [formState, setFormState] = useState<PolicyFormState>({
    name: "",
    principalRole: initialData?.principal?.role || null,
    resourceType: initialData?.resource?.type || null,
    actions: initialData?.action ? [initialData.action] : [],
    conditionExpression: initialData?.condition?.expression || "",
    conditionDescription: initialData?.condition?.description || "",
  });

  // 현재 스텝
  const [currentStep, setCurrentStep] = useState(0);

  // 완료된 스텝
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);

  // 저장 상태
  const [isSaving, setIsSaving] = useState(false);

  // 에러 메시지
  const [errors, setErrors] = useState<Record<number, string>>({});

  // Principal 옵션
  const principalOptions = [
    { value: "admin" as const, label: "Admin", description: "전체 권한" },
    { value: "editor" as const, label: "Editor", description: "편집 권한" },
    { value: "viewer" as const, label: "Viewer", description: "조회 권한" },
  ];

  // Resource 옵션
  const resourceOptions = [
    { value: "document" as const, label: "Document", description: "문서 리소스" },
    { value: "issue" as const, label: "Issue", description: "이슈 리소스" },
  ];

  // Action 옵션
  const actionOptions = [
    { value: "read" as const, label: "Read", description: "읽기 작업" },
    { value: "write" as const, label: "Write", description: "쓰기 작업" },
    { value: "delete" as const, label: "Delete", description: "삭제 작업" },
  ];

  // 스텝 유효성 검사
  const validateStep = useCallback((stepIndex: number): StepValidation => {
    switch (stepIndex) {
      case 0:
        if (!formState.name.trim()) {
          return { isValid: false, error: "정책 이름을 입력하세요" };
        }
        if (formState.name.length > 100) {
          return { isValid: false, error: "정책 이름은 100자 이내여야 합니다" };
        }
        if (!formState.principalRole) {
          return { isValid: false, error: "Principal 역할을 선택하세요" };
        }
        return { isValid: true };
      case 1:
        if (!formState.resourceType) {
          return { isValid: false, error: "Resource 유형을 선택하세요" };
        }
        return { isValid: true };
      case 2:
        if (formState.actions.length === 0) {
          return { isValid: false, error: "최소 하나 이상의 Action을 선택하세요" };
        }
        return { isValid: true };
      case 3:
        return { isValid: true };
      default:
        return { isValid: true };
    }
  }, [formState]);

  // 전체 유효성 검사
  const isAllValid = useMemo(() => {
    return (
      formState.name.trim().length > 0 &&
      formState.name.length <= 100 &&
      formState.principalRole !== null &&
      formState.resourceType !== null &&
      formState.actions.length > 0
    );
  }, [formState]);

  // Cedar JSON 생성
  const cedarJson = useMemo(() => {
    const policy: CedarPolicy = {
      effect: "forbid",
      principal: {
        role: formState.principalRole || "viewer",
      },
      resource: {
        type: formState.resourceType || "document",
      },
      action: formState.actions[0] || "read",
    };

    if (formState.conditionExpression.trim()) {
      policy.condition = {
        expression: formState.conditionExpression,
        description: formState.conditionDescription || formState.conditionExpression,
      };
    }

    return JSON.stringify(policy, null, 2);
  }, [formState]);

  // Principal 선택
  const handlePrincipalSelect = (value: "admin" | "editor" | "viewer") => {
    setFormState((prev) => ({ ...prev, principalRole: value }));
    setErrors((prev) => ({ ...prev, 0: "" }));
  };

  // Resource 선택
  const handleResourceSelect = (value: "document" | "issue") => {
    setFormState((prev) => ({ ...prev, resourceType: value }));
    setErrors((prev) => ({ ...prev, 1: "" }));
  };

  // Action 토글
  const handleActionToggle = (value: "read" | "write" | "delete") => {
    setFormState((prev) => {
      const exists = prev.actions.includes(value);
      return {
        ...prev,
        actions: exists
          ? prev.actions.filter((a) => a !== value)
          : [...prev.actions, value],
      };
    });
    setErrors((prev) => ({ ...prev, 2: "" }));
  };

  // 전체 Action 선택
  const handleSelectAllActions = () => {
    setFormState((prev) => ({
      ...prev,
      actions: actionOptions.map((a) => a.value),
    }));
    setErrors((prev) => ({ ...prev, 2: "" }));
  };

  // 전체 Action 해제
  const handleSelectNoneActions = () => {
    setFormState((prev) => ({ ...prev, actions: [] }));
  };

  // 다음 스텝
  const handleNext = () => {
    const validation = validateStep(currentStep);
    if (!validation.isValid) {
      setErrors((prev) => ({ ...prev, [currentStep]: validation.error || "" }));
      return;
    }

    if (!completedSteps.includes(currentStep)) {
      setCompletedSteps((prev) => [...prev, currentStep]);
    }

    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    }
  };

  // 이전 스텝
  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  // 스텝 클릭
  const handleStepClick = (index: number) => {
    if (index <= currentStep || completedSteps.includes(index)) {
      setCurrentStep(index);
    }
  };

  // 저장
  const handleSave = async () => {
    if (!isAllValid) {
      return;
    }

    setIsSaving(true);
    try {
      if (onSave) {
        await onSave(cedarJson, formState.name);
      }
      // 폼 초기화
      setFormState({
        name: "",
        principalRole: null,
        resourceType: null,
        actions: [],
        conditionExpression: "",
        conditionDescription: "",
      });
      setCurrentStep(0);
      setCompletedSteps([]);
    } catch (error) {
      console.error("Save failed:", error);
    } finally {
      setIsSaving(false);
    }
  };

  // 취소
  const handleCancel = () => {
    if (onCancel) {
      onCancel();
    }
  };

  // 스타일 정의
  const containerStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-container"),
    backgroundColor: t("--color-background-surface"),
    border: `1px solid ${t("--color-border")}`,
    maxWidth: "800px",
    margin: "0 auto",
  };

  const headerStyle: React.CSSProperties = {
    marginBottom: "1.5rem",
    paddingBottom: "1rem",
    borderBottom: `1px solid ${t("--color-border")}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1.25rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
    marginBottom: "1rem",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "0.75rem",
    fontSize: "0.875rem",
    borderRadius: t("--radius-element"),
    border: `1px solid ${errors[0] ? "#ef4444" : t("--color-border")}`,
    backgroundColor: t("--color-background-surface"),
    color: t("--color-text-primary"),
    outline: "none",
    boxSizing: "border-box" as const,
  };

  const navigationStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    marginTop: "1.5rem",
    gap: "1rem",
  };

  const buttonBaseStyle: React.CSSProperties = {
    padding: "0.75rem 1.5rem",
    fontSize: "0.875rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    border: "none",
  };

  const primaryButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: t("--color-accent"),
    color: "white",
    opacity: isAllValid ? 1 : 0.5,
    cursor: isAllValid && !isSaving ? "pointer" : "not-allowed",
  };

  const secondaryButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: "transparent",
    color: t("--color-text-secondary"),
    border: `1px solid ${t("--color-border")}`,
  };

  const previewContainerStyle: React.CSSProperties = {
    marginTop: "1.5rem",
    padding: "1rem",
    borderRadius: t("--radius-element"),
    backgroundColor: t("--color-background-muted"),
    border: `1px solid ${t("--color-border")}`,
  };

  const previewTitleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    marginBottom: "0.5rem",
  };

  const codeBlockStyle: React.CSSProperties = {
    fontFamily: "JetBrains Mono, monospace",
    fontSize: "0.75rem",
    color: t("--color-text-secondary"),
    whiteSpace: "pre-wrap" as const,
    wordBreak: "break-all" as const,
    margin: 0,
    padding: "0.75rem",
    backgroundColor: t("--color-background-body"),
    borderRadius: t("--radius-inner"),
    overflow: "auto" as const,
    maxHeight: "200px",
  };

  const footerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    marginTop: "1.5rem",
    paddingTop: "1rem",
    borderTop: `1px solid ${t("--color-border")}`,
  };

  // 스텝 콘텐츠 렌더링
  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div>
            <div style={{ marginBottom: "1rem" }}>
              <label
                htmlFor="policyName"
                style={{
                  display: "block",
                  marginBottom: "0.5rem",
                  fontSize: "0.875rem",
                  fontWeight: 500,
                  color: t("--color-text-primary"),
                }}
              >
                Policy Name *
              </label>
              <input
                id="policyName"
                type="text"
                value={formState.name}
                onChange={(e) => {
                  setFormState((prev) => ({ ...prev, name: e.target.value }));
                  setErrors((prev) => ({ ...prev, 0: "" }));
                }}
                placeholder="정책 이름을 입력하세요"
                style={inputStyle}
              />
            </div>
            <StepContainer
              title="Principal (Role)"
              subtitle="역할을 선택하세요"
              error={errors[0]}
              onSelectAll={() => {}}
              onSelectNone={() => {}}
            >
              {principalOptions.map((option) => (
                <SelectionCard
                  key={option.value}
                  title={option.label}
                  description={option.description}
                  selected={formState.principalRole === option.value}
                  onClick={() => handlePrincipalSelect(option.value)}
                />
              ))}
            </StepContainer>
          </div>
        );

      case 1:
        return (
          <StepContainer
            title="Resource Type"
            subtitle="리소스 유형을 선택하세요"
            error={errors[1]}
            onSelectAll={() => {}}
            onSelectNone={() => {}}
          >
            {resourceOptions.map((option) => (
              <SelectionCard
                key={option.value}
                title={option.label}
                description={option.description}
                selected={formState.resourceType === option.value}
                onClick={() => handleResourceSelect(option.value)}
              />
            ))}
          </StepContainer>
        );

      case 2:
        return (
          <StepContainer
            title="Action"
            subtitle="작업을 선택하세요 (다중 선택 가능)"
            showBulkActions
            error={errors[2]}
            onSelectAll={handleSelectAllActions}
            onSelectNone={handleSelectNoneActions}
          >
            {actionOptions.map((option) => (
              <SelectionCard
                key={option.value}
                title={option.label}
                description={option.description}
                selected={formState.actions.includes(option.value)}
                onClick={() => handleActionToggle(option.value)}
              />
            ))}
          </StepContainer>
        );

      case 3:
        return (
          <StepContainer
            title="Condition (선택)"
            subtitle="조건 표현식을 입력하세요 (선택사항)"
            onSelectAll={() => {}}
            onSelectNone={() => {}}
          >
            <div style={{ width: "100%" }}>
              <label
                htmlFor="conditionExpression"
                style={{
                  display: "block",
                  marginBottom: "0.5rem",
                  fontSize: "0.875rem",
                  fontWeight: 500,
                  color: t("--color-text-primary"),
                }}
              >
                Condition Expression
              </label>
              <input
                id="conditionExpression"
                type="text"
                value={formState.conditionExpression}
                onChange={(e) =>
                  setFormState((prev) => ({
                    ...prev,
                    conditionExpression: e.target.value,
                  }))
                }
                placeholder='예: resource.ownerId == principal.id'
                style={{
                  ...inputStyle,
                  fontFamily: "JetBrains Mono, monospace",
                }}
              />
              <div style={{ marginTop: "1rem" }}>
                <label
                  htmlFor="conditionDescription"
                  style={{
                    display: "block",
                    marginBottom: "0.5rem",
                    fontSize: "0.875rem",
                    fontWeight: 500,
                    color: t("--color-text-primary"),
                  }}
                >
                  Condition Description (선택)
                </label>
                <input
                  id="conditionDescription"
                  type="text"
                  value={formState.conditionDescription}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      conditionDescription: e.target.value,
                    }))
                  }
                  placeholder="조건에 대한 설명을 입력하세요"
                  style={inputStyle}
                />
              </div>
            </div>
          </StepContainer>
        );

      default:
        return null;
    }
  };

  return (
    <div style={containerStyle}>
      <header style={headerStyle}>
        <h2 style={titleStyle}>Policy Editor</h2>
      </header>

      <StepperProgress
        steps={steps}
        currentStep={currentStep}
        completedSteps={completedSteps}
        onStepClick={handleStepClick}
      />

      {renderStepContent()}

      <div style={navigationStyle}>
        <button
          style={secondaryButtonStyle}
          onClick={handlePrevious}
          disabled={currentStep === 0}
          type="button"
        >
          ← Previous
        </button>
        {currentStep < steps.length - 1 ? (
          <button
            style={primaryButtonStyle}
            onClick={handleNext}
            type="button"
          >
            Next →
          </button>
        ) : (
          <div />
        )}
      </div>

      <div style={previewContainerStyle}>
        <h3 style={previewTitleStyle}>Cedar JSON Preview</h3>
        <pre style={codeBlockStyle}>{cedarJson}</pre>
      </div>

      <footer style={footerStyle}>
        <button
          style={secondaryButtonStyle}
          onClick={handleCancel}
          type="button"
        >
          Cancel
        </button>
        <button
          style={primaryButtonStyle}
          onClick={handleSave}
          disabled={!isAllValid || isSaving}
          type="button"
        >
          {isSaving ? "Saving..." : "Save Policy"}
        </button>
      </footer>
    </div>
  );
};

export default PolicyEditor;

/**
 * ResultDisplay Component
 * 
 * Displays the authorization evaluation result with visual badges.
 */

import { useTheme } from "@astryxdesign/core";
import type { EvaluateResponse } from "../types/evaluation";

interface ResultDisplayProps {
  result: EvaluateResponse | null;
}

export function ResultDisplay({ result }: ResultDisplayProps) {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  if (!result) {
    return null;
  }

  const isAllow = result.decision === "ALLOW";

  const containerStyle: React.CSSProperties = {
    marginTop: "1rem",
  };

  const badgeStyle: React.CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    gap: "0.5rem",
    padding: "0.75rem 1.5rem",
    borderRadius: t("--radius-element"),
    fontSize: "1.25rem",
    fontWeight: 600,
    backgroundColor: isAllow ? "#22c55e" : "#ef4444",
    color: "white",
  };

  const iconStyle: React.CSSProperties = {
    width: "1.5rem",
    height: "1.5rem",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  };

  const detailsStyle: React.CSSProperties = {
    marginTop: "1rem",
    padding: "1rem",
    backgroundColor: t("--color-background-muted"),
    borderRadius: t("--radius-element"),
    border: `1px solid ${t("--color-border")}`,
  };

  const labelStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    color: t("--color-text-secondary"),
    marginBottom: "0.25rem",
  };

  const valueStyle: React.CSSProperties = {
    fontSize: "1rem",
    color: t("--color-text-primary"),
    fontWeight: 500,
  };

  return (
    <div style={containerStyle}>
      <div style={badgeStyle}>
        <span style={iconStyle}>{isAllow ? "✓" : "✗"}</span>
        <span>{result.decision}</span>
      </div>

      {isAllow ? (
        <div style={detailsStyle}>
          <p style={{ color: t("--color-text-secondary"), margin: 0 }}>
            모든 Forbid 정책이 미매칭 → 요청이 허용됩니다
          </p>
        </div>
      ) : (
        <div style={detailsStyle}>
          <div style={{ marginBottom: "0.75rem" }}>
            <p style={labelStyle}>매칭된 정책</p>
            <p style={valueStyle}>{result.matchedPolicy || "-"}</p>
          </div>
          {result.reason && (
            <div>
              <p style={labelStyle}>이유</p>
              <p style={valueStyle}>{result.reason}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * TestPanel Component
 * 
 * Authorization testing panel that allows users to configure and evaluate
 * authorization requests against the Cedar policy engine.
 */

import { useState, useCallback, useEffect } from "react";
import { useTheme } from "@astryxdesign/core";
import { useEvaluate } from "../hooks/useEvaluate";
import { ResultDisplay } from "./ResultDisplay";
import type { Principal, Resource, EvaluateRequest, EvaluateResponse } from "../types/evaluation";

/**
 * Sample data for the dropdowns
 */
const SAMPLE_USERS: Record<string, string[]> = {
  admin: ["user-admin", "admin-001"],
  editor: ["user-editor", "editor-001"],
  viewer: ["user-viewer", "viewer-001"],
};

const SAMPLE_RESOURCES: Record<string, { id: string; ownerId: string; attributes: Resource["attributes"] }[]> = {
  document: [
    { id: "doc-001", ownerId: "user-admin", attributes: { isPublic: true, author: "admin" } },
    { id: "doc-002", ownerId: "user-admin", attributes: { isPublic: false, author: "admin" } },
    { id: "doc-003", ownerId: "user-editor", attributes: { isPublic: true, author: "editor" } },
  ],
  issue: [
    { id: "issue-001", ownerId: "user-admin", attributes: { author: "admin" } },
    { id: "issue-002", ownerId: "user-viewer", attributes: { author: "viewer" } },
  ],
};

const ACTIONS: Array<{ value: "read" | "write" | "delete"; label: string }> = [
  { value: "read", label: "Read" },
  { value: "write", label: "Write" },
  { value: "delete", label: "Delete" },
];

export function TestPanel() {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);
  const { evaluate, loading, error } = useEvaluate();

  // Form state
  const [principalRole, setPrincipalRole] = useState<Principal["role"]>("viewer");
  const [principalId, setPrincipalId] = useState<string>("user-viewer");
  const [resourceType, setResourceType] = useState<Resource["type"]>("document");
  const [resourceId, setResourceId] = useState<string>("doc-001");
  const [selectedActions, setSelectedActions] = useState<Set<string>>(new Set(["read"]));

  // Result state
  const [result, setResult] = useState<EvaluateResponse | null>(null);

  // Get current resource details
  const currentResource = SAMPLE_RESOURCES[resourceType]?.find((r) => r.id === resourceId);

  // Update principal ID when role changes
  useEffect(() => {
    const users = SAMPLE_USERS[principalRole];
    if (users && users.length > 0) {
      setPrincipalId(users[0]);
    }
  }, [principalRole]);

  // Update resource ID when type changes
  useEffect(() => {
    const resources = SAMPLE_RESOURCES[resourceType];
    if (resources && resources.length > 0) {
      setResourceId(resources[0].id);
    }
  }, [resourceType]);

  const handleActionToggle = useCallback((action: string) => {
    setSelectedActions((prev) => {
      const next = new Set(prev);
      if (next.has(action)) {
        next.delete(action);
      } else {
        next.add(action);
      }
      return next;
    });
  }, []);

  const handleEvaluate = useCallback(async () => {
    if (selectedActions.size === 0) {
      return;
    }

    // Use the first selected action for evaluation
    const action = Array.from(selectedActions)[0] as "read" | "write" | "delete";

    const request: EvaluateRequest = {
      principal: {
        role: principalRole,
        id: principalId,
      },
      resource: {
        type: resourceType,
        id: resourceId,
        ownerId: currentResource?.ownerId || "unknown",
        attributes: currentResource?.attributes,
      },
      action,
    };

    const response = await evaluate(request);
    setResult(response);
  }, [principalRole, principalId, resourceType, resourceId, currentResource, selectedActions, evaluate]);

  // Styles
  const panelStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: t("--radius-container"),
    backgroundColor: t("--color-background-surface"),
    border: `1px solid ${t("--color-border")}`,
  };

  const headerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "1.5rem",
    paddingBottom: "1rem",
    borderBottom: `1px solid ${t("--color-border")}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: t("--text-heading-1-size"),
    fontWeight: Number(t("--text-heading-1-weight")),
    color: t("--color-text-primary"),
    margin: 0,
  };

  const badgeStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    padding: "0.25rem 0.5rem",
    borderRadius: t("--radius-inner"),
    backgroundColor: t("--color-accent"),
    color: "white",
  };

  const sectionStyle: React.CSSProperties = {
    marginBottom: "1.5rem",
  };

  const sectionTitleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    marginBottom: "0.75rem",
  };

  const fieldGroupStyle: React.CSSProperties = {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
    gap: "1rem",
  };

  const fieldStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "0.5rem",
  };

  const labelStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    fontWeight: 500,
    color: t("--color-text-secondary"),
    textTransform: "uppercase",
    letterSpacing: "0.05em",
  };

  const inputStyle: React.CSSProperties = {
    padding: "0.5rem 0.75rem",
    borderRadius: t("--radius-element"),
    border: `1px solid ${t("--color-border")}`,
    backgroundColor: t("--color-background-surface"),
    color: t("--color-text-primary"),
    fontSize: "0.875rem",
  };

  const readonlyFieldStyle: React.CSSProperties = {
    ...inputStyle,
    backgroundColor: t("--color-background-muted"),
    cursor: "not-allowed",
  };

  const checkboxGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "1rem",
    flexWrap: "wrap",
  };

  const checkboxLabelStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    gap: "0.5rem",
    cursor: "pointer",
    fontSize: "0.875rem",
    color: t("--color-text-primary"),
  };

  const buttonStyle: React.CSSProperties = {
    width: "100%",
    padding: "0.75rem 1rem",
    borderRadius: t("--radius-element"),
    border: "none",
    backgroundColor: t("--color-accent"),
    color: "white",
    fontSize: "1rem",
    fontWeight: 600,
    cursor: loading ? "not-allowed" : "pointer",
    opacity: loading ? 0.7 : 1,
    transition: `background-color ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const errorStyle: React.CSSProperties = {
    marginTop: "1rem",
    padding: "0.75rem",
    borderRadius: t("--radius-element"),
    backgroundColor: "#fef2f2",
    border: "1px solid #fecaca",
    color: "#dc2626",
    fontSize: "0.875rem",
  };

  return (
    <div style={panelStyle}>
      <header style={headerStyle}>
        <h2 style={titleStyle}>Authorization Test</h2>
        <span style={badgeStyle}>Playground</span>
      </header>

      {/* Request Configuration */}
      <div style={sectionStyle}>
        <h3 style={sectionTitleStyle}>Request Configuration</h3>

        {/* Principal */}
        <div style={{ marginBottom: "1rem" }}>
          <label style={labelStyle}>Principal</label>
          <div style={fieldGroupStyle}>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>Role</label>
              <select
                value={principalRole}
                onChange={(e) => setPrincipalRole(e.target.value as Principal["role"])}
                style={inputStyle}
              >
                <option value="admin">Admin</option>
                <option value="editor">Editor</option>
                <option value="viewer">Viewer</option>
              </select>
            </div>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>User ID</label>
              <select
                value={principalId}
                onChange={(e) => setPrincipalId(e.target.value)}
                style={inputStyle}
              >
                {SAMPLE_USERS[principalRole]?.map((userId) => (
                  <option key={userId} value={userId}>
                    {userId}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Resource */}
        <div style={{ marginBottom: "1rem" }}>
          <label style={labelStyle}>Resource</label>
          <div style={fieldGroupStyle}>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>Type</label>
              <select
                value={resourceType}
                onChange={(e) => setResourceType(e.target.value as Resource["type"])}
                style={inputStyle}
              >
                <option value="document">Document</option>
                <option value="issue">Issue</option>
              </select>
            </div>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>Resource ID</label>
              <select
                value={resourceId}
                onChange={(e) => setResourceId(e.target.value)}
                style={inputStyle}
              >
                {SAMPLE_RESOURCES[resourceType]?.map((resource) => (
                  <option key={resource.id} value={resource.id}>
                    {resource.id}
                  </option>
                ))}
              </select>
            </div>
          </div>
          {/* Resource Attributes (readonly) */}
          <div style={{ marginTop: "0.75rem", display: "flex", gap: "1rem", flexWrap: "wrap" }}>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>Owner</label>
              <input
                type="text"
                value={currentResource?.ownerId || "-"}
                readOnly
                style={readonlyFieldStyle}
              />
            </div>
            <div style={fieldStyle}>
              <label style={{ ...labelStyle, fontSize: "0.75rem" }}>isPublic</label>
              <input
                type="text"
                value={currentResource?.attributes?.isPublic?.toString() || "false"}
                readOnly
                style={readonlyFieldStyle}
              />
            </div>
          </div>
        </div>

        {/* Action */}
        <div>
          <label style={labelStyle}>Action</label>
          <div style={checkboxGroupStyle}>
            {ACTIONS.map((action) => (
              <label key={action.value} style={checkboxLabelStyle}>
                <input
                  type="checkbox"
                  checked={selectedActions.has(action.value)}
                  onChange={() => handleActionToggle(action.value)}
                />
                <span>{action.label}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Evaluate Button */}
      <div>
        <button
          onClick={handleEvaluate}
          disabled={loading || selectedActions.size === 0}
          style={buttonStyle}
        >
          {loading ? "Evaluating..." : "Evaluate Request"}
        </button>
        {selectedActions.size === 0 && (
          <p style={{ ...errorStyle, backgroundColor: "#fef3c7", borderColor: "#fcd34d", color: "#92400e", marginTop: "0.5rem" }}>
            최소 1개의 액션을 선택해주세요.
          </p>
        )}
      </div>

      {/* Error Display */}
      {error && <div style={errorStyle}>{error}</div>}

      {/* Result Display */}
      <div>
        <h3 style={{ ...sectionTitleStyle, marginTop: "1.5rem" }}>Result</h3>
        <ResultDisplay result={result} />
      </div>
    </div>
  );
}
